using System;
using Customization;

public class UomMigrationV3 : CustomizationPlugin
{
    // Set to null for Phase 2 (all companies)
    private const string TARGET_COMPANY = null; // null = ALL companies

    private Microsoft.Data.SqlClient.SqlConnection _conn;
    private Microsoft.Data.SqlClient.SqlTransaction _tx;
    private int _targetId = -1;
    private string _companyFilter = "";

    public override void UpdateDatabase()
    {
        WriteLog("=== UOM Migration v3: INSERT-then-flip (PIECE→YDS + PIECENBR→BOLTID) ===");
        WriteLog($"TARGET_COMPANY = {(TARGET_COMPANY ?? "(all)")}");

        var cs = System.Configuration.ConfigurationManager.ConnectionStrings["ProjectX"];
        if (cs == null) { WriteLog("ERROR: No connection string."); return; }

        string connStr = cs.ConnectionString + ";TrustServerCertificate=True";
        try
        {
            using (_conn = new Microsoft.Data.SqlClient.SqlConnection(connStr))
            {
                _conn.Open();

                // ── Company discovery ──
                if (TARGET_COMPANY != null)
                {
                    using (var cmd = _conn.CreateCommand())
                    {
                        cmd.CommandText = "SELECT TOP 1 CompanyID FROM Company WHERE CompanyCD = @name";
                        cmd.Parameters.AddWithValue("@name", TARGET_COMPANY);
                        cmd.CommandTimeout = 10;
                        var result = cmd.ExecuteScalar();
                        if (result == null)
                        {
                            WriteLog($"ERROR: Company '{TARGET_COMPANY}' not found.");
                            return;
                        }
                        _targetId = (int)result;
                    }
                    _companyFilter = $" AND CompanyID = {_targetId}";
                    WriteLog($"Company '{TARGET_COMPANY}' → CompanyID = {_targetId}");
                }
                else
                {
                    _companyFilter = "";
                    WriteLog("Running for ALL companies.");
                }

                // ── Pre-flight counts ──
                int pieceBaseCount = Scalar($"SELECT COUNT(*) FROM InventoryItem WHERE BaseUnit = 'PIECE'{_companyFilter}");
                int pieceFromCount = Scalar($"SELECT COUNT(*) FROM INUnit WHERE FromUnit = 'PIECE'{_companyFilter}");
                int piecenbrCount  = Scalar($"SELECT COUNT(*) FROM InventoryItem WHERE LotSerClassID = 'PIECENBR'{_companyFilter}");
                WriteLog($"Pre-flight: {pieceBaseCount} items with BaseUnit=PIECE, {pieceFromCount} INUnit rows with FromUnit=PIECE, {piecenbrCount} items with LotSerClassID=PIECENBR");

                if (pieceBaseCount == 0 && pieceFromCount == 0 && piecenbrCount == 0)
                {
                    WriteLog("Nothing to migrate. Exiting early.");
                    return;
                }

                // ── BEGIN TRANSACTION ──
                _tx = _conn.BeginTransaction();
                try
                {
                    // ── Section 1: INSERT missing YDS→YDS self-conversions ──
                    WriteLog("--- Section 1: INSERT missing YDS→YDS self-conversions ---");
                    Exec($@"INSERT INTO INUnit (CompanyID, UnitType, ItemClassID, InventoryID,
                                FromUnit, ToUnit, UnitRate, UnitMultDiv,
                                PriceAdjustmentMultiplier, CompanyMask,
                                CreatedByID, CreatedByScreenID, CreatedDateTime,
                                LastModifiedByID, LastModifiedByScreenID, LastModifiedDateTime)
                            SELECT CompanyID, UnitType, ItemClassID, InventoryID,
                                   'YDS', 'YDS', UnitRate, UnitMultDiv,
                                   PriceAdjustmentMultiplier, CompanyMask,
                                   CreatedByID, CreatedByScreenID, GETUTCDATE(),
                                   LastModifiedByID, LastModifiedByScreenID, GETUTCDATE()
                            FROM INUnit src
                            WHERE src.FromUnit = 'PIECE' AND src.ToUnit = 'PIECE'
                            AND NOT EXISTS (
                                SELECT 1 FROM INUnit dup
                                WHERE dup.CompanyID = src.CompanyID
                                AND dup.UnitType = src.UnitType
                                AND dup.ItemClassID = src.ItemClassID
                                AND dup.InventoryID = src.InventoryID
                                AND dup.FromUnit = 'YDS' AND dup.ToUnit = 'YDS'
                            ){_companyFilter}", "INUnit INSERT YDS→YDS self-conversions");

                    // ── Section 2: Flip BaseUnit and SalesUnit ──
                    WriteLog("--- Section 2: Flip BaseUnit and SalesUnit ---");
                    Exec($"UPDATE InventoryItem SET BaseUnit = 'YDS' WHERE BaseUnit = 'PIECE'{_companyFilter}", "InventoryItem.BaseUnit");
                    Exec($"UPDATE InventoryItem SET SalesUnit = 'YDS' WHERE SalesUnit = 'PIECE'{_companyFilter}", "InventoryItem.SalesUnit");
                    Exec($"UPDATE INItemClass SET BaseUnit = 'YDS' WHERE BaseUnit = 'PIECE'{_companyFilter}", "INItemClass.BaseUnit");
                    Exec($"UPDATE INItemClass SET SalesUnit = 'YDS' WHERE SalesUnit = 'PIECE'{_companyFilter}", "INItemClass.SalesUnit");

                    // ── Section 3: Inventory transactions ──
                    WriteLog("--- Section 3: Inventory transactions ---");
                    Safe($"UPDATE INTran SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "INTran.UOM");
                    Safe($"UPDATE INTranSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "INTranSplit.UOM");

                    // ── Section 4: Sales Order tables ──
                    WriteLog("--- Section 4: Sales Order tables ---");
                    Safe($"UPDATE SOLine SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "SOLine.UOM");
                    Safe($"UPDATE SOLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "SOLineSplit.UOM");
                    Safe($"UPDATE SOShipLine SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "SOShipLine.UOM");
                    Safe($"UPDATE SOShipLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "SOShipLineSplit.UOM");
                    Safe($"UPDATE SOPackageDetailEx SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "SOPackageDetailEx.UOM");

                    // ── Section 5: Purchase Order tables ──
                    WriteLog("--- Section 5: Purchase Order tables ---");
                    Safe($"UPDATE POLine SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "POLine.UOM");
                    Safe($"UPDATE POLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "POLineSplit.UOM");
                    Safe($"UPDATE POReceiptLine SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "POReceiptLine.UOM");
                    Safe($"UPDATE POReceiptLineSplit SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "POReceiptLineSplit.UOM");

                    // ── Section 6: AR/AP transaction tables ──
                    WriteLog("--- Section 6: AR/AP transaction tables ---");
                    Safe($"UPDATE ARTran SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "ARTran.UOM");
                    Safe($"UPDATE APTran SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "APTran.UOM");

                    // ── Section 7: Pricing tables ──
                    WriteLog("--- Section 7: Pricing tables ---");
                    Safe($"UPDATE ARSalesPrice SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "ARSalesPrice.UOM");
                    Safe($"UPDATE APVendorPrice SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "APVendorPrice.UOM");

                    // ── Section 8: Misc inventory tables ──
                    WriteLog("--- Section 8: Misc inventory tables ---");
                    Safe($"UPDATE INPIDetail SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "INPIDetail.UOM");
                    Safe($"UPDATE INKitSpecStkDet SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "INKitSpecStkDet.UOM");
                    Safe($"UPDATE INKitSpecNonStkDet SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "INKitSpecNonStkDet.UOM");
                    Safe($"UPDATE INItemPlan SET UOM = 'YDS' WHERE UOM = 'PIECE'{_companyFilter}", "INItemPlan.UOM");
                    Safe($"UPDATE INItemCustSalesStats SET BaseUOM = 'YDS' WHERE BaseUOM = 'PIECE'{_companyFilter}", "INItemCustSalesStats.BaseUOM");

                    // ── Section 9: Lot/Serial Class rename PIECENBR → BOLTID ──
                    // Uses Safe() because INLotSerClassSegment may not exist in all versions
                    WriteLog("--- Section 9: Lot/Serial Class rename PIECENBR → BOLTID ---");
                    Safe($"UPDATE InventoryItem SET LotSerClassID = 'BOLTID' WHERE LotSerClassID = 'PIECENBR'{_companyFilter}", "InventoryItem.LotSerClassID");
                    Safe($"UPDATE INItemClass SET LotSerClassID = 'BOLTID' WHERE LotSerClassID = 'PIECENBR'{_companyFilter}", "INItemClass.LotSerClassID");
                    Safe($"UPDATE INLotSerClassSegment SET LotSerClassID = 'BOLTID' WHERE LotSerClassID = 'PIECENBR'{_companyFilter}", "INLotSerClassSegment.LotSerClassID");
                    Safe($"UPDATE INLotSerClass SET LotSerClassID = 'BOLTID' WHERE LotSerClassID = 'PIECENBR'{_companyFilter}", "INLotSerClass.LotSerClassID");

                    // ── COMMIT ──
                    _tx.Commit();
                    _tx = null;
                    WriteLog("TRANSACTION COMMITTED.");
                }
                catch (Exception txEx)
                {
                    try { _tx.Rollback(); } catch { }
                    WriteLog($"TRANSACTION ROLLED BACK: {txEx.Message}");
                    WriteLog($"Stack: {txEx.StackTrace}");
                    return;
                }

                // ── Post-flight counts ──
                int postPieceBase = Scalar($"SELECT COUNT(*) FROM InventoryItem WHERE BaseUnit = 'PIECE'{_companyFilter}");
                int postPieceFrom = Scalar($"SELECT COUNT(*) FROM INUnit WHERE FromUnit = 'PIECE'{_companyFilter}");
                int postPiecenbr  = Scalar($"SELECT COUNT(*) FROM InventoryItem WHERE LotSerClassID = 'PIECENBR'{_companyFilter}");
                WriteLog($"Post-flight: {postPieceBase} items with BaseUnit=PIECE, {postPieceFrom} INUnit rows with FromUnit=PIECE, {postPiecenbr} items with LotSerClassID=PIECENBR");

                WriteLog("=== UOM Migration v3 COMPLETE ===");
            }
        }
        catch (Exception ex)
        {
            WriteLog($"ERROR: {ex.Message}");
            WriteLog($"Stack: {ex.StackTrace}");
        }
    }

    private int Scalar(string sql)
    {
        using (var cmd = _conn.CreateCommand())
        {
            if (_tx != null) cmd.Transaction = _tx;
            cmd.CommandText = sql;
            cmd.CommandTimeout = 30;
            var result = cmd.ExecuteScalar();
            return result != null ? (int)result : 0;
        }
    }

    private void Exec(string sql, string label)
    {
        using (var cmd = _conn.CreateCommand())
        {
            cmd.Transaction = _tx;
            cmd.CommandText = sql;
            cmd.CommandTimeout = 120;
            int rows = cmd.ExecuteNonQuery();
            WriteLog($"  {label}: {rows} row(s)");
        }
    }

    private void Safe(string sql, string label)
    {
        try
        {
            Exec(sql, label);
        }
        catch (Microsoft.Data.SqlClient.SqlException ex) when (ex.Number == 207 || ex.Number == 208)
        {
            WriteLog($"  {label}: SKIPPED (table/column not found)");
        }
    }
}
